/* 马儿快跑 · 账单图片（Canvas 2D · 零依赖 · file:// 可用）
   window.BillImage = { open(orderId), render(orderId), save(), share() }
   逻辑宽 750px，2x 输出；品牌头内嵌 base64，避免 file:// 下 Canvas 被本地图片污染。 */
(function (root) {
  'use strict';

  var HEADER_B64 = '';
  var FONT = '-apple-system, "PingFang SC", "Microsoft YaHei", sans-serif';
  var W = 750;
  var PAD = 40;
  var SCALE = 2;

  var INK = '#0D0E11';
  var BRAND = '#F5B301';
  var CREAM = '#FFF8E6';
  var MUTED = '#8A8A90';
  var LINE = '#E8E2D6';
  var PAPER = '#FFFDF7';
  var BRAND_INK = '#7A5A00';
  var OK_GREEN = '#1F6B3B';

  var METHOD = { wechat: '微信', alipay: '支付宝', cash: '现金', credit: '欠款' };
  var STATUS = {
    PENDING_DISPATCH: '待派单', PENDING_PREP: '待商家备货', READY_FOR_PICKUP: '备货完成',
    PICKED_UP: '已取货', DELIVERING: '配送中', DELIVERED: '已送达',
    FINISHED: '已结单', CANCELLED: '已取消'
  };

  var measureCanvas = null;
  var header = null;
  var last = null;

  function store() { return root.Store || null; }

  function money(fen) {
    if (root.UI && typeof root.UI.money === 'function') return root.UI.money(fen);
    return '¥' + (Number(fen || 0) / 100).toFixed(2);
  }

  function pad2(n) { return (n < 10 ? '0' : '') + n; }

  function fmtDateTime(iso) {
    var d = new Date(iso);
    if (isNaN(d.getTime())) return '—';
    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) +
      ' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());
  }

  function fmtShort(iso) {
    var d = new Date(iso);
    if (isNaN(d.getTime())) return '—';
    return pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) + ' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());
  }

  function measureCtx() {
    if (!measureCanvas) {
      measureCanvas = root.document.createElement('canvas');
      measureCanvas.width = 16;
      measureCanvas.height = 16;
    }
    return measureCanvas.getContext('2d');
  }

  function rr(ctx, x, y, w, h, r) {
    var rad = Math.min(r, h / 2, w / 2);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function headerReady() { return !!(header && header.complete && header.naturalWidth > 0); }

  function toast(msg, kind) {
    try {
      if (root.UI && typeof root.UI.toast === 'function') root.UI.toast(msg, kind || 'ok');
    } catch (e) { /* ignore */ }
  }

  /* ---------- 取数 ---------- */
  function buildBill(orderId) {
    var S = store();
    var o = null;
    try { o = S && typeof S.order === 'function' ? S.order(orderId) : null; } catch (e) { o = null; }
    if (!o) return { id: orderId, order: null };

    var groups = [];
    try {
      var gs = S.groupsOf ? S.groupsOf(o) : (o.merchantGroups || []);
      groups = (gs || []).map(function (g, i) {
        var name = g.merchantName || '';
        if (!name && S.merchant && g.merchantId) {
          var m = S.merchant(g.merchantId);
          name = m ? m.name : '';
        }
        return {
          seq: i + 1,
          name: name || '未命名商家',
          items: (g.items || []).map(function (it) { return String(it.text || '').trim(); }).filter(Boolean).join('、') || '—',
          note: g.note || '',
          hasReal: g.goodsRealFen != null,
          realFen: g.goodsRealFen != null ? Number(g.goodsRealFen) : null,
          estFen: Number(g.goodsEstFen || 0)
        };
      });
    } catch (e) { groups = []; }

    var c = null, u = null;
    try { c = S.customer ? S.customer(o.customerId) : null; } catch (e) { c = null; }
    try { u = c && S.user ? S.user(c.userId) : null; } catch (e) { u = null; }
    var addr = o.address || {};

    var pays = [];
    try {
      if (S.paymentsOf) {
        pays = S.paymentsOf(o.id) || [];
      } else {
        pays = (S.get ? S.get().ledger : []).filter(function (e) {
          return e.orderId === Number(o.id) && e.type === 'PAYMENT';
        }).sort(function (a, b) { return new Date(a.at) - new Date(b.at); });
      }
    } catch (e) { pays = []; }

    var fallbackGoods = groups.reduce(function (s, g) { return s + (g.hasReal ? g.realFen : g.estFen); }, 0);
    var goods = fallbackGoods;
    try { if (S.orderGoodsFen) goods = S.orderGoodsFen(o); } catch (e) { goods = fallbackGoods; }

    var service = Number(o.serviceFeeFen || 0);
    var extra = Number(o.extraFeeFen || 0);
    var discount = Number(o.discountFen || 0);
    var receivable, paid, owed;
    try { receivable = S.receivable(o); } catch (e) { receivable = goods + service + extra - discount; }
    try { paid = S.paidOf(o.id); } catch (e) {
      paid = pays.reduce(function (s, p) { return s + Math.abs(Number(p.amountFen || 0)); }, 0);
    }
    try { owed = S.owedOf(o); } catch (e) { owed = Math.max(0, receivable - paid); }

    var serviceName = '';
    try {
      var st = S.serviceType ? S.serviceType(o.serviceType) : null;
      serviceName = st ? st.name : '';
    } catch (e) { serviceName = ''; }

    var status = '';
    try { status = S.statusLabel ? S.statusLabel(o) : (STATUS[o.status] || o.status || ''); }
    catch (e) { status = STATUS[o.status] || o.status || ''; }

    return {
      id: o.id,
      order: o,
      groups: groups,
      payments: pays,
      customer: {
        name: (u && u.name) || addr.contactName || '客户',
        phone: (u && u.phone) || addr.phone || '',
        note: (c && c.note) || ''
      },
      serviceName: serviceName,
      status: status,
      amounts: {
        goods: goods, service: service, extra: extra, discount: discount,
        receivable: receivable, paid: paid, owed: owed
      }
    };
  }

  /* ---------- 绘制 ---------- */
  function paint(bill) {
    var ops = [];
    var mctx = measureCtx();
    var y = 0;

    function font(size, weight) { return (weight || 400) + ' ' + size + 'px ' + FONT; }

    function add(fn) { ops.push(fn); }

    function wrap(text, size, weight, maxW) {
      mctx.font = font(size, weight);
      var src = String(text == null ? '' : text);
      var lines = [];
      var cur = '';
      for (var i = 0; i < src.length; i++) {
        var ch = src.charAt(i);
        if (ch === '\n') { lines.push(cur); cur = ''; continue; }
        var test = cur + ch;
        if (cur && mctx.measureText(test).width > maxW) { lines.push(cur); cur = ch; }
        else cur = test;
      }
      lines.push(cur);
      return lines;
    }

    function text(str, x, baseline, size, color, weight, align) {
      add(function (ctx) {
        ctx.font = font(size, weight);
        ctx.fillStyle = color || INK;
        ctx.textAlign = align || 'left';
        ctx.fillText(String(str == null ? '' : str), x, baseline);
        ctx.textAlign = 'left';
      });
    }

    function divider(at, dashed, from, to) {
      add(function (ctx) {
        ctx.save();
        ctx.strokeStyle = LINE;
        ctx.lineWidth = 1;
        if (dashed && ctx.setLineDash) ctx.setLineDash([7, 7]);
        ctx.beginPath();
        ctx.moveTo(from == null ? PAD : from, at);
        ctx.lineTo(to == null ? W - PAD : to, at);
        ctx.stroke();
        ctx.restore();
      });
    }

    function section(at, title, more) {
      add(function (ctx) {
        ctx.fillStyle = BRAND;
        ctx.fillRect(PAD, at - 20, 6, 24);
        ctx.font = font(24, 800);
        ctx.fillStyle = INK;
        ctx.fillText(title, PAD + 16, at);
        if (more) {
          ctx.font = font(19);
          ctx.fillStyle = MUTED;
          ctx.textAlign = 'right';
          ctx.fillText(more, W - PAD, at);
          ctx.textAlign = 'left';
        }
      });
    }

    /* 底 + 品牌头 */
    add(function (ctx, height) {
      ctx.fillStyle = '#FFFFFF';
      ctx.fillRect(0, 0, W, height);
    });
    if (headerReady()) {
      add(function (ctx) { ctx.drawImage(header, 0, 0, W, 150); });
    } else {
      add(function (ctx) {
        ctx.fillStyle = CREAM;
        ctx.fillRect(0, 0, W, 150);
        ctx.fillStyle = INK;
        ctx.font = font(36, 800);
        ctx.fillText('马儿快跑', PAD, 74);
        ctx.font = font(21);
        ctx.fillStyle = MUTED;
        ctx.fillText('马儿跑得快，诚信赢天下', PAD, 110);
        ctx.font = font(26, 800);
        ctx.fillStyle = INK;
        ctx.textAlign = 'right';
        ctx.fillText('账单', W - PAD, 80);
        ctx.textAlign = 'left';
      });
    }
    add(function (ctx) { ctx.fillStyle = BRAND; ctx.fillRect(0, 150, W, 6); });
    y = 150 + 6 + 52;

    function footer() {
      y += 26;
      divider(y);
      y += 48;
      text('马儿跑得快，诚信赢天下', W / 2, y, 26, INK, 800, 'center');
      y += 34;
      text('生成于 ' + fmtDateTime(new Date().toISOString()), W / 2, y, 19, MUTED, 400, 'center');
      y += 28;
      text('本单由马儿快跑出具，仅供对账使用，不作为发票', W / 2, y, 18, MUTED, 400, 'center');
      y += 30;
      add(function (ctx, height) { ctx.fillStyle = BRAND; ctx.fillRect(0, height - 10, W, 10); });
    }

    if (!bill.order) {
      text('账单 #' + bill.id, PAD, y, 32, INK, 800);
      text('订单不存在或已删除，无法生成完整账单', PAD, y + 42, 22, MUTED);
      y += 90;
      footer();
    } else {
      var o = bill.order;
      var c = bill.customer;
      var a = bill.amounts;
      var anyUnrecorded = bill.groups.some(function (g) { return !g.hasReal; });

      /* 订单号 / 日期 / 状态 */
      text(o.no, PAD, y, 34, INK, 800);
      text(o.finishedAt ? '结单 ' + fmtDateTime(o.finishedAt) : '下单 ' + fmtDateTime(o.createdAt),
        W - PAD, y - 8, 19, MUTED, 400, 'right');
      y += 34;
      var meta = bill.status || '';
      if (bill.serviceName) meta += ' · ' + bill.serviceName;
      if (meta) text(meta, PAD, y, 21, BRAND_INK, 600);
      y += 26;
      divider(y);
      y += 36;

      /* 客户 */
      var customerLine = c.name + (c.note ? '（' + c.note + '）' : '');
      text('客户', PAD, y, 20, MUTED);
      var nameLines = wrap(customerLine, 24, 700, W - PAD * 2 - 92);
      nameLines.forEach(function (ln, i) { text(ln, PAD + 92, y + i * 32, 24, INK, 700); });
      y += (nameLines.length - 1) * 32;
      if (c.phone) {
        y += 30;
        text('手机', PAD, y, 20, MUTED);
        text(c.phone, PAD + 92, y, 23, INK);
      }
      y += 34;

      /* 商家组 */
      section(y, '商家明细', bill.groups.length ? bill.groups.length + ' 组' : '无商家组');
      y += 24;
      if (!bill.groups.length) {
        text('本单没有商家组（纯跑腿 / 代办 / 代驾）', PAD, y + 18, 22, MUTED);
        y += 42;
      } else {
        bill.groups.forEach(function (g) {
          var itemLines = wrap('物品：' + g.items, 21, 400, W - PAD * 2 - 44);
          var noteLines = (g.note && g.note !== g.items) ? wrap('备注：' + g.note, 19, 400, W - PAD * 2 - 44) : [];
          var cardTop = y;
          var cardH = 24 + 34 + itemLines.length * 30 + noteLines.length * 26 + 20;
          add((function (gg, top, hh, iLines, nLines) {
            return function (ctx) {
              ctx.fillStyle = PAPER;
              rr(ctx, PAD, top, W - PAD * 2, hh, 14);
              ctx.fill();
              ctx.strokeStyle = LINE;
              ctx.lineWidth = 1;
              rr(ctx, PAD, top, W - PAD * 2, hh, 14);
              ctx.stroke();

              ctx.font = font(24, 750);
              ctx.fillStyle = INK;
              ctx.fillText(gg.seq + '. ' + gg.name, PAD + 22, top + 48);

              ctx.textAlign = 'right';
              ctx.font = font(26, 800);
              ctx.fillStyle = gg.hasReal ? INK : MUTED;
              ctx.fillText(gg.hasReal ? money(gg.realFen) : '未录', W - PAD - 22, top + 48);
              ctx.textAlign = 'left';

              ctx.font = font(21);
              ctx.fillStyle = MUTED;
              var by = top + 80;
              iLines.forEach(function (ln) { ctx.fillText(ln, PAD + 22, by); by += 30; });
              ctx.font = font(19);
              nLines.forEach(function (ln) { ctx.fillText(ln, PAD + 22, by); by += 26; });
            };
          })(g, cardTop, cardH, itemLines, noteLines));
          y = cardTop + cardH + 12;
        });
        if (anyUnrecorded) {
          text('「未录」表示骑手尚未录入实付，货款合计暂按估价计算', PAD, y + 8, 18, MUTED);
          y += 26;
        }
      }

      /* 金额 */
      y += 6;
      section(y, '金额明细', '');
      y += 24;
      var rows = [
        { k: anyUnrecorded ? '货款（含未录估价）' : '货款', v: money(a.goods) },
        { k: '跑腿费', v: money(a.service) },
        { k: '附加费', v: money(a.extra) },
        { k: '优惠', v: a.discount > 0 ? '-' + money(a.discount) : money(0) },
        { k: '应收', v: money(a.receivable), strong: true, top: true },
        { k: '已收', v: money(a.paid) },
        { k: '未收', v: money(a.owed), strong: a.owed > 0, brand: a.owed > 0 }
      ];
      var cardPad = 24;
      var rowH = 48;
      var amountCardH = cardPad * 2 + rows.length * rowH + 4;
      var amountTop = y;
      add((function (top, hh) {
        return function (ctx) {
          ctx.fillStyle = '#FFFFFF';
          rr(ctx, PAD, top, W - PAD * 2, hh, 14);
          ctx.fill();
          ctx.strokeStyle = INK;
          ctx.lineWidth = 1.5;
          rr(ctx, PAD, top, W - PAD * 2, hh, 14);
          ctx.stroke();
        };
      })(amountTop, amountCardH));
      var rowY = amountTop + cardPad + 22;
      rows.forEach(function (r) {
        if (r.top) divider(rowY - 34, false, PAD + 22, W - PAD - 22);
        text(r.k, PAD + 24, rowY, 22, MUTED);
        text(r.v, W - PAD - 24, rowY, r.strong ? 27 : 23, r.brand ? BRAND_INK : INK, r.strong ? 800 : 700, 'right');
        rowY += rowH;
      });
      y = amountTop + amountCardH + 20;

      /* 收款记录 */
      section(y, '收款记录', bill.payments.length ? bill.payments.length + ' 笔' : '0 笔');
      y += 24;
      if (!bill.payments.length) {
        text('暂无收款记录（未收款或整单欠款）', PAD, y + 16, 21, MUTED);
        y += 34;
      } else {
        bill.payments.forEach(function (p, idx) {
          var rowTop = y;
          var note = p.note ? String(p.note) : '';
          var operator = p.operator ? '经办 ' + p.operator : '';
          var sub = [note, operator].filter(Boolean).join(' · ');
          var subLines = sub ? wrap(sub, 19, 400, W - PAD * 2 - 140) : [];

          text(fmtShort(p.at), PAD, rowTop + 22, 21, INK, 600);
          add((function (top, pm) {
            return function (ctx) {
              var label = METHOD[pm] || pm || '—';
              ctx.font = font(18, 600);
              var tw = ctx.measureText(label).width;
              ctx.fillStyle = CREAM;
              rr(ctx, PAD + 130, top + 4, tw + 20, 26, 13);
              ctx.fill();
              ctx.fillStyle = BRAND_INK;
              ctx.textAlign = 'left';
              ctx.fillText(label, PAD + 140, top + 22);
            };
          })(rowTop, p.method));
          text('+' + money(Math.abs(Number(p.amountFen || 0))), W - PAD, rowTop + 22, 24, OK_GREEN, 800, 'right');

          var by = rowTop + 48;
          subLines.forEach(function (ln) {
            text(ln, PAD + 130, by, 19, MUTED);
            by += 26;
          });
          y = by + 8;
          if (idx < bill.payments.length - 1) {
            divider(y - 2, true);
            y += 18;
          }
        });
      }
      y += 4;
      footer();
    }

    var H = Math.max(1000, Math.round(y + 40));
    var canvas = root.document.createElement('canvas');
    canvas.width = W * SCALE;
    canvas.height = H * SCALE;
    var ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('浏览器不支持 Canvas 2D');
    ctx.scale(SCALE, SCALE);
    for (var i = 0; i < ops.length; i++) ops[i](ctx, H);

    return { dataUrl: canvas.toDataURL('image/png'), height: H };
  }

  function render(orderId) {
    return paint(buildBill(orderId)).dataUrl;
  }

  /* ---------- 预览 / 保存 / 分享 ---------- */
  function showPreview(dataUrl, orderId) {
    var S = store();
    var o = null;
    try { o = S && S.order ? S.order(orderId) : null; } catch (e) { o = null; }
    var no = o ? o.no : String(orderId);
    last = { dataUrl: dataUrl, filename: '账单-' + no + '.png' };

    var mask = root.document.createElement('div');
    mask.className = 'modal-mask';
    mask.style.zIndex = '80';
    mask.innerHTML =
      '<div class="modal" role="dialog" aria-modal="true" aria-label="账单图片预览">' +
      '<div class="modal-hd">账单图片' +
      '<span class="small muted" style="margin-left:4px;font-weight:400">长按图片也可保存</span>' +
      '<button type="button" class="btn sm ghost" data-x="close">关闭</button></div>' +
      '<div class="modal-bd" style="padding:12px;background:#F1EDE3">' +
      '<img alt="账单图片预览" style="width:100%;height:auto;display:block;border-radius:10px;background:#fff;box-shadow:0 2px 12px rgba(13,14,17,.16)">' +
      '</div>' +
      '<div class="modal-ft">' +
      '<button type="button" class="btn ghost" data-x="close">关闭</button>' +
      '<button type="button" class="btn" data-x="share">分享账单</button>' +
      '<button type="button" class="btn pri" data-x="save">保存图片</button>' +
      '</div></div>';

    mask.querySelector('img').src = dataUrl;
    root.document.body.appendChild(mask);

    function close() {
      if (mask.parentNode) mask.parentNode.removeChild(mask);
    }
    mask.addEventListener('click', function (e) { if (e.target === mask) close(); });
    Array.prototype.forEach.call(mask.querySelectorAll('[data-x="close"]'), function (b) {
      b.addEventListener('click', close);
    });
    mask.querySelector('[data-x="save"]').addEventListener('click', function () { save(); });
    mask.querySelector('[data-x="share"]').addEventListener('click', function () { share(); });
  }

  function open(orderId) {
    var id = Number(orderId);
    function go() {
      try {
        var out = paint(buildBill(id));
        showPreview(out.dataUrl, id);
      } catch (e) {
        if (root.console) root.console.error(e);
        toast(e && e.message ? e.message : '生成账单图片失败', 'err');
      }
    }
    if (headerReady() || !header) { go(); return; }
    var done = false;
    var timer = setTimeout(function () { if (!done) { done = true; go(); } }, 700);
    function ready() {
      if (done) return;
      done = true;
      clearTimeout(timer);
      go();
    }
    header.addEventListener('load', ready);
    header.addEventListener('error', ready);
  }

  function download() {
    if (!last || !last.dataUrl) { toast('还没有生成账单图片', 'err'); return false; }
    var a = root.document.createElement('a');
    a.href = last.dataUrl;
    a.download = last.filename;
    a.rel = 'noopener';
    root.document.body.appendChild(a);
    a.click();
    root.document.body.removeChild(a);
    return true;
  }

  function save() {
    var ok = download();
    if (ok) toast('已保存账单图片', 'ok');
    return ok;
  }

  function dataUrlToFile(dataUrl, name) {
    var parts = String(dataUrl).split(',');
    var m = /data:([^;]+)/.exec(parts[0] || '');
    var bin = root.atob(parts[1] || '');
    var len = bin.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return new root.File([bytes], name, { type: m ? m[1] : 'image/png' });
  }

  function share() {
    if (!last || !last.dataUrl) { toast('先生成账单图片', 'err'); return; }
    var file = null;
    try { file = dataUrlToFile(last.dataUrl, last.filename); } catch (e) { file = null; }

    var canShare = false;
    try {
      var nav = root.navigator || {};
      canShare = !!(file && typeof nav.share === 'function' &&
        (!nav.canShare || nav.canShare({ files: [file] })));
    } catch (e) { canShare = false; }

    if (!canShare) { download(); return; }

    try {
      var p = root.navigator.share({
        files: [file],
        title: last.filename.replace(/\.png$/i, ''),
        text: '马儿快跑 · 账单'
      });
      if (p && typeof p.catch === 'function') p.catch(function () { download(); });
    } catch (e) {
      download();
    }
  }

  try {
    header = new root.Image();
    header.src = 'data:image/png;base64,' + HEADER_B64;
  } catch (e) { header = null; }

  root.BillImage = {
    open: open,
    render: render,
    save: save,
    share: share
  };
})(typeof globalThis !== 'undefined' ? globalThis : this);
